using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpStdioServer;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the JSONPlaceholder API.")]
    public static async Task<string> FetchPostAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve (1–100).")] int postId)
    {
        using var client = httpClientFactory.CreateClient("api");
        var response = await client.GetAsync($"/posts/{postId}");
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var root = doc.RootElement;

        return $"""
            Post #{root.GetProperty("id")}
            Title: {root.GetProperty("title").GetString()}
            Body:  {root.GetProperty("body").GetString()}
            """;
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpStdioServer;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks an LLM to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Maximum number of sentences in the summary (default: 3).")] int maxSentences = 3)
    {
        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"""
                        Summarize the following text in at most {maxSentences} sentences.
                        Be concise and capture the key points.

                        ---
                        {text}
                        ---
                        """
                }
            }
        ];
    }
}

